class Solution {
public:
    int characterReplacement(string s, int k) {
        vector<int> cnt(26, 0);
        int left = 0, maxFreq = 0, answer = 0;
        for (int right = 0; right < (int)s.size(); ++right) {
            cnt[s[right] - 'A']++;
            maxFreq = max(maxFreq, cnt[s[right] - 'A']);
            while (right - left + 1 - maxFreq > k) {
                cnt[s[left] - 'A']--;
                ++left;
            }
            answer = max(answer, right - left + 1);
        }
        return answer;
    }
};
